import React, { useState } from 'react';
import { getSwitchState, switchStyleKeys } from '../lib/core';
import type { SwitchBaseProps } from '../lib/core';
import styles from './switch.module.scss';

export interface SwitchProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'onChange'>, SwitchBaseProps {
	checked?: boolean;
	defaultChecked?: boolean;
	onCheckedChange?: (checked: boolean) => void;
}

const Switch = React.forwardRef<HTMLButtonElement, SwitchProps>(
	({ className = '', size = 'default', checked, defaultChecked = false, disabled, onCheckedChange, ...props }, ref) => {
		const [internalChecked, setInternalChecked] = useState(defaultChecked);
		const isChecked = checked !== undefined ? checked : internalChecked;
		const state = getSwitchState(isChecked);

		function handleClick(event: React.MouseEvent<HTMLButtonElement>) {
			const next = !isChecked;

			if (checked === undefined) {
				setInternalChecked(next);
			}

			onCheckedChange?.(next);
			props.onClick?.(event);
		}

		return (
			<button
				ref={ref}
				type="button"
				role="switch"
				aria-checked={isChecked}
				data-state={state}
				data-size={size}
				disabled={disabled}
				className={`${styles[switchStyleKeys.root]} ${className}`}
				{...props}
				onClick={handleClick}>
				<span className={styles[switchStyleKeys.thumb]} />
			</button>
		);
	},
);

Switch.displayName = 'Switch';

export { Switch };
export default Switch;

@use '../../../styles/variables/colors' as *;

.root {
	display: inline-flex;
	flex-shrink: 0;
	align-items: center;
	border-radius: $radius-full;
	border: 1px solid transparent;
	box-shadow: $shadow-sm;
	transition: background-color $transition-fast;
	outline: none;

	&:focus-visible {
		border-color: $ring;
		box-shadow:
			0 0 0 1px $ring,
			0 0 0 3px color-mix(in srgb, $ring 50%, transparent);
	}

	&:disabled {
		cursor: not-allowed;
		opacity: 0.5;
	}

	&[data-size='default'] {
		width: 2rem;
		height: 1.15rem;
	}

	&[data-size='sm'] {
		width: 1.5rem;
		height: 0.875rem;
	}

	&[data-state='checked'] {
		background-color: $primary;
	}

	&[data-state='unchecked'] {
		background-color: $input;
	}
}

.thumb {
	pointer-events: none;
	display: block;
	border-radius: $radius-full;
	background-color: $background;
	transition: transform $transition-normal;

	[data-size='default'] & {
		width: 1rem;
		height: 1rem;
	}

	[data-size='sm'] & {
		width: 0.75rem;
		height: 0.75rem;
	}

	[data-state='checked'] & {
		transform: translateX(calc(100% - 2px));
	}

	[data-state='unchecked'] & {
		transform: translateX(0);
	}
}
